sys_ui_action.script:
// Refresh all prices
// total_price = (base_price + delivery_price + additional_cost) - discount_amount 
// base_price = sum of all of the offerings x quantity
const orderGR = current;
const offeringsToOrders = new GlideRecord("x_1128327_cake_offerings_to_orders");
offeringsToOrders.addQuery("order", orderGR.getValue("sys_id"));
offeringsToOrders.query();

// Recalculate the base price
var basePrice = 0;
while(offeringsToOrders.next()) {
	const offeringPrice = parseFloat(offeringsToOrders.offering.total_price + "");
	const qty = parseInt(offeringsToOrders.getValue("quantity"));
	basePrice += offeringPrice * qty;
}
orderGR.basePrice = basePrice.toFixed(2);

// Recalculate the delivery price if this is a delivery and the 'Charge per mile' setting exists
var deliveryPrice = 0;
const settingGR = new GlideRecord("x_1128327_cake_settings");
if (orderGR.getValue("delivery") == "1" && settingGR.get("name", "Charge per mile")) {
	const miles = parseFloat(orderGR.getValue("miles"));
	const pricePerMile = parseFloat(settingGR.getValue("value"));
	deliveryPrice = miles * pricePerMile;
	orderGR.delivery_price = deliveryPrice.toFixed(2);
}

// Set the total_price
const addCost = parseFloat(orderGR.getValue("additional_cost"));
const discAmount = parseFloat(orderGR.getValue("discount_amount"));
orderGR.total_price = ((basePrice + deliveryPrice + addCost) - discAmount).toFixed(2);
orderGR.update();
action.setRedirectURL(orderGR);
